Find the area of the shaded region bounded by $y=x^{2}$, the $x$-axis and the lines $x=1$ and $x=3$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.25cm, y=0.42cm]
\fill[gray!35, domain=1:3, variable=\x] (1,0) -- plot ({\x},{\x*\x}) -- (3,0) -- cycle;
\draw[->] (-1.1,0) -- (4.1,0) node[right] {$x$};
\draw[->] (0,-1.8) -- (0,13.4) node[above] {$y$};
\draw[thick, <->, domain=-0.6:3.5, smooth, samples=100, variable=\x] plot ({\x},{\x*\x});
\draw[dashed] (3,0) -- (3,9);
\node[below] at (1,0) {$1$};
\node[below] at (3,0) {$3$};
\node[left] at (0,10) {$10$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=3x-12$, the $x$-axis and the lines $x=0$ and $x=3$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.9cm, y=0.24cm]
\fill[gray!35, domain=0:3, variable=\x] (0,0) -- plot ({\x},{3*\x-12}) -- (3,0) -- cycle;
\draw[->] (-1.6,0) -- (6.4,0) node[right] {$x$};
\draw[->] (0,-15.6) -- (0,7.4) node[above] {$y$};
\draw[thick, <->, domain=-1:5.8, smooth, samples=100, variable=\x] plot ({\x},{3*\x-12});
\node[above right] at (3,0) {$3$};
\node[left] at (0,-5) {$-5$};
\node[left] at (0,-10) {$-10$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=x^{2}-1$, the $x$-axis and the lines $x=0$ and $x=2$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.4cm, y=0.85cm]
\fill[gray!35, domain=0:1, variable=\x] (0,0) -- plot ({\x},{\x*\x-1}) -- (1,0) -- cycle;
\fill[gray!35, domain=1:2, variable=\x] (1,0) -- plot ({\x},{\x*\x-1}) -- (2,0) -- cycle;
\draw[->] (-2.6,0) -- (2.8,0) node[right] {$x$};
\draw[->] (0,-1.9) -- (0,4.7) node[above] {$y$};
\draw[thick, <->, domain=-2.2:2.3, smooth, samples=100, variable=\x] plot ({\x},{\x*\x-1});
\draw[dashed] (2,0) -- (2,3);
\node[above left] at (1,0) {$1$};
\node[below right] at (2,0) {$2$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region enclosed between the curve $y=4-x^{2}$ and the $x$-axis.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.2cm, y=0.6cm]
\fill[gray!35, domain=-2:2, variable=\x] (-2,0) -- plot ({\x},{4-\x*\x}) -- (2,0) -- cycle;
\draw[->] (-3.2,0) -- (3.3,0) node[right] {$x$};
\draw[->] (0,-4.2) -- (0,5.6) node[above] {$y$};
\draw[thick, <->, domain=-2.8:2.8, smooth, samples=100, variable=\x] plot ({\x},{4-\x*\x});
\node[below left] at (-2,0) {$-2$};
\node[below right] at (2,0) {$2$};
\end{tikzpicture}
[/tikz]

The shaded region is bounded by $y=x^{2}-3x$, the $x$-axis and the lines $x=1$ and $x=4$. Find the **value** of $\int_{1}^{4}\left(x^{2}-3x\right)dx$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.1cm, y=0.5cm]
\fill[gray!35, domain=1:3, variable=\x] (1,0) -- plot ({\x},{\x*\x-3*\x}) -- (3,0) -- cycle;
\fill[gray!35, domain=3:4, variable=\x] (3,0) -- plot ({\x},{\x*\x-3*\x}) -- (4,0) -- cycle;
\draw[->] (-1.5,0) -- (5.2,0) node[right] {$x$};
\draw[->] (0,-3.4) -- (0,7.4) node[above] {$y$};
\draw[thick, <->, domain=-1:4.6, smooth, samples=100, variable=\x] plot ({\x},{\x*\x-3*\x});
\draw[dashed] (4,0) -- (4,4);
\node[above left] at (1,0) {$1$};
\node[above] at (3,0) {$3$};
\node[below right] at (4,0) {$4$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=-x^{3}$, the $x$-axis and the lines $x=2$ and $x=3$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.9cm, y=0.09cm]
\fill[gray!35, domain=2:3, variable=\x] (2,0) -- plot ({\x},{-\x*\x*\x}) -- (3,0) -- cycle;
\draw[->] (-4,0) -- (4.2,0) node[right] {$x$};
\draw[->] (0,-42) -- (0,42) node[above] {$y$};
\draw[thick, <->, domain=-3.3:3.3, smooth, samples=120, variable=\x] plot ({\x},{-\x*\x*\x});
\node[above] at (2,0) {$2$};
\node[above right] at (3,0) {$3$};
\node[left] at (0,20) {$20$};
\node[left] at (0,-20) {$-20$};
\end{tikzpicture}
[/tikz]

The shaded region is bounded by $y=2x$, the $x$-axis and the lines $x=0$ and $x=k$, where $k>0$. The area of the region is $49$ square units. Find the value of $k$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.6cm, y=0.28cm]
\fill[gray!35, domain=0:8, variable=\x] (0,0) -- plot ({\x},{2*\x}) -- (8,0) -- cycle;
\draw[->] (-2.6,0) -- (10.4,0) node[right] {$x$};
\draw[->] (0,-5.4) -- (0,21.4) node[above] {$y$};
\draw[thick, <->, domain=-2:9.6, smooth, samples=100, variable=\x] plot ({\x},{2*\x});
\draw[dashed] (8,0) -- (8,16);
\node[below] at (8,0) {$x=k$};
\node[left] at (0,10) {$10$};
\node[left] at (0,20) {$20$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=x^{3}-9x$, the $x$-axis and the lines $x=0$ and $x=4$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.05cm, y=0.15cm]
\fill[gray!35, domain=0:3, variable=\x] (0,0) -- plot ({\x},{\x*\x*\x-9*\x}) -- (3,0) -- cycle;
\fill[gray!35, domain=3:4, variable=\x] (3,0) -- plot ({\x},{\x*\x*\x-9*\x}) -- (4,0) -- cycle;
\draw[->] (-4.8,0) -- (5.2,0) node[right] {$x$};
\draw[->] (0,-22) -- (0,33) node[above] {$y$};
\draw[thick, <->, domain=-3.8:4.1, smooth, samples=140, variable=\x] plot ({\x},{\x*\x*\x-9*\x});
\draw[dashed] (4,0) -- (4,28);
\node[above left] at (3,0) {$3$};
\node[below right] at (4,0) {$4$};
\node[left] at (0,20) {$20$};
\node[left] at (0,-20) {$-20$};
\end{tikzpicture}
[/tikz]

Find the total area of the shaded region enclosed between the curve $y=4x-x^{3}$ and the $x$-axis.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.5cm, y=0.6cm]
\fill[gray!35, domain=-2:0, variable=\x] (-2,0) -- plot ({\x},{4*\x-\x*\x*\x}) -- (0,0) -- cycle;
\fill[gray!35, domain=0:2, variable=\x] (0,0) -- plot ({\x},{4*\x-\x*\x*\x}) -- (2,0) -- cycle;
\draw[->] (-2.9,0) -- (3,0) node[right] {$x$};
\draw[->] (0,-4.6) -- (0,5.2) node[above] {$y$};
\draw[thick, <->, domain=-2.4:2.4, smooth, samples=140, variable=\x] plot ({\x},{4*\x-\x*\x*\x});
\node[above left] at (-2,0) {$-2$};
\node[below right] at (2,0) {$2$};
\end{tikzpicture}
[/tikz]
